export function findResourceArticleFeature({ slug = '', title = '' } = {}) {
  const normalizedSlug = String(slug || '').trim().toLowerCase();
  const normalizedTitle = String(title || '').trim().toLowerCase();
  return resourceArticleFeatureCatalog.find((article) => (
    (normalizedSlug && article.slug === normalizedSlug)
      || (normalizedTitle && article.title.toLowerCase() === normalizedTitle)
  )) || null;
}

export function getResourceArticleFeatureSelection(article) {
  const selected = article && typeof article === 'object' ? article : null;
  return {
    slug: String(selected?.slug || '').trim(),
    title: String(selected?.title || '').trim(),
    imageUrl: String(selected?.imageUrl || '').trim(),
    to: selected?.slug ? `${RESOURCE_ARTICLE_ROUTE_PREFIX}${encodeURIComponent(selected.slug)}` : '',
  };
}

